/* ============================================================
   gsocd-shared / order-tracker
   Tracker de pasos donde el marcador de cada puntito es un
   fragmento ACUMULATIVO del triangulo del logo real (no un punto
   ni un diamante generico) -- cada puntito ya alcanzado muestra el
   triangulo armado hasta ESE punto; al llegar al ultimo gajo entra
   la G y despues la S.

   Mismo patron que el resto de gsocd-shared: un solo <style>
   inyectado una vez, estado por fieldId (varios trackers pueden
   convivir en la misma pagina), API minima expuesta en
   window.GSOrderTracker.

   Uso:
     GSOrderTracker.mount('order-GS-2026-0512', 'tracker-mount', {
       steps: [
         { label:'Creada',       stage:'Orden creada',
           detail:'Recibida en oficina — 2 sep', kind:'wedge' },
         { label:'Cambio pedido',stage:'Cambio solicitado',
           detail:'El cliente pidió mover la fecha — 3 sep', kind:'wedge' },
         ...
         { label:'En servicio',  stage:'En servicio',
           detail:'Asignado: Carlos Martínez — 8 sep', kind:'g' },
         { label:'Completada',   stage:'Orden completada',
           detail:'Completado por: Carlos Martínez — 8 sep', kind:'s' }
       ],
       current: 5   // cuantos pasos de la lista ya pasaron de verdad
     });

     // cuando llega un evento nuevo de verdad (polling / websocket / etc):
     GSOrderTracker.setCurrent('order-GS-2026-0512', 6);

   Reglas de "kind":
     'wedge' -> cuenta como un gajo del triangulo (el numero total de
                gajos = cuantos steps de tipo 'wedge' haya en total).
     'g'     -> el triangulo ya deberia estar completo a estas alturas;
                ademas entra la G.
     's'     -> triangulo + G ya puestos; entra la S (logo completo).

   Clic en un puntito YA PASADO muestra su detalle abajo sin mover el
   avance real de la orden (se ve la etiqueta "Revisando un paso
   anterior"). Avanzar el progreso real (setCurrent) siempre regresa
   la vista al paso actual.
============================================================ */
(function () {
  'use strict';

  var STYLE_ID = 'gs-trk-style';
  var TRI_D = 'M141.77,6.05 L209.78,829.96 L892.14,356.10 Z';

  /* Mismas piezas en alta resolucion que ya se probaron en el mini --
     una sola copia aqui, la comparten los 3 portales via jsDelivr. */
  var LAYER_G = 'data:image/png;base64,';
  var LAYER_S = 'data:image/png;base64,';

  var instances = {};   // fieldId -> {steps, current, viewIndex, containerId}
  var sharedTriLen = null; // largo del trazo del triangulo, se mide una sola vez (es el mismo path siempre)

  function styleTag() {
    if (document.getElementById(STYLE_ID)) return;
    var css =
      '.gs-trk-scroll{overflow-x:auto;padding-bottom:6px}' +
      '.gs-trk-tracker{display:flex;align-items:flex-start;min-width:520px;padding:0 4px;gap:2px}' +
      '.gs-trk-step{flex:1;display:flex;flex-direction:column;align-items:center;text-align:center}' +
      '.gs-trk-dot{width:64px;height:64px;display:flex;align-items:center;justify-content:center;' +
        'position:relative;filter:drop-shadow(0 0 0 rgba(201,168,76,0));transition:filter .4s}' +
      '.gs-trk-step.now .gs-trk-dot{filter:drop-shadow(0 0 8px rgba(201,168,76,.55))}' +
      '.gs-trk-step.regression .gs-trk-dot-gold{stroke:#B33A3A}' +
      '.gs-trk-step.regression .gs-trk-step-label{color:#B33A3A;font-weight:600}' +
      '.gs-trk-step.viewing .gs-trk-dot{filter:drop-shadow(0 0 8px rgba(107,107,107,.5))}' +
      '.gs-trk-step.clickable .gs-trk-dot{cursor:pointer}' +
      '.gs-trk-step.clickable:hover .gs-trk-dot{filter:drop-shadow(0 0 6px rgba(107,107,107,.35))}' +
      '.gs-trk-dot-icon{width:60px;height:60px;overflow:visible;position:absolute;inset:0}' +
      '.gs-trk-dot-gold{fill:none;stroke:var(--gold-dk,#8C6F2A);stroke-width:60;stroke-linejoin:round;' +
        'stroke-linecap:round;transition:stroke-dashoffset .6s ease}' +
      '.gs-trk-dot-letters{position:absolute;inset:0;display:flex}' +
      '.gs-trk-dot-letters img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;' +
        'opacity:0;transition:opacity .5s, -webkit-mask-image .6s ease, mask-image .6s ease}' +
      '.gs-trk-step-label{font-size:10px;color:var(--gray,#6B6B6B);margin-top:8px;line-height:1.35;max-width:78px}' +
      '.gs-trk-step.done .gs-trk-step-label{color:var(--black,#111)}' +
      '.gs-trk-step.now .gs-trk-step-label{color:var(--black,#111);font-weight:600}' +
      '.gs-trk-stage-row{margin-top:20px;padding-top:14px;border-top:1px solid var(--border,#E0D9CC)}' +
      '.gs-trk-viewing-tag{font-size:9.5px;text-transform:uppercase;letter-spacing:.05em;' +
        'color:var(--gray,#6B6B6B);font-weight:700;margin-bottom:4px}' +
      '.gs-trk-stage-name{font-family:\'Cormorant Garamond\',serif;font-size:18px;font-weight:600;color:var(--black,#111)}' +
      '.gs-trk-stage-sub{font-size:11.5px;color:var(--gray,#6B6B6B);margin-top:2px}';
    var tag = document.createElement('style');
    tag.id = STYLE_ID;
    tag.textContent = css;
    document.head.appendChild(tag);
  }

  function esc(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }

  function measureTriLen() {
    if (sharedTriLen != null) return sharedTriLen;
    var svgNS = 'http://www.w3.org/2000/svg';
    var svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('style', 'position:absolute;width:0;height:0;overflow:hidden');
    var path = document.createElementNS(svgNS, 'path');
    path.setAttribute('d', TRI_D);
    svg.appendChild(path);
    document.body.appendChild(svg);
    sharedTriLen = path.getTotalLength();
    document.body.removeChild(svg);
    return sharedTriLen;
  }

  /* fraccion del triangulo para una etapa dada -- ya NO cuenta cuantos
     eventos tipo 'wedge' han pasado (eso solo podia subir). Ahora es
     una funcion directa de en que etapa quedo la orden despues de ESE
     evento (resultStage, que el llamador ya calculo) -- si la orden
     retrocede a una etapa anterior, esto regresa un numero mas chico
     tambien, y el triangulo visualmente se encoge. */
  function triFracFor(resultStage, triangleMaxStage) {
    if (!triangleMaxStage) return 0;
    return Math.max(0, Math.min(1, resultStage / triangleMaxStage));
  }

  function render(fieldId) {
    var inst = instances[fieldId];
    if (!inst) return;
    var el = document.getElementById(inst.containerId);
    if (!el) return;

    var steps = inst.steps;
    var current = inst.current;
    var viewIndex = inst.viewIndex;
    var gStage = inst.gStage;
    var sStage = inst.sStage;
    var triangleMaxStage = inst.triangleMaxStage;
    var triLen = measureTriLen();

    var stageHtml;
    if (viewIndex !== null) {
      var ev = steps[viewIndex];
      stageHtml =
        '<div class="gs-trk-viewing-tag">Revisando un paso anterior</div>' +
        '<div class="gs-trk-stage-name">' + esc(ev.stage) + '</div>' +
        '<div class="gs-trk-stage-sub">' + esc(ev.detail || '') + '</div>';
    } else if (current === 0) {
      stageHtml =
        '<div class="gs-trk-stage-name">Todavía no arranca</div>' +
        '<div class="gs-trk-stage-sub"></div>';
    } else {
      var cur = steps[current - 1];
      stageHtml =
        '<div class="gs-trk-stage-name">' + esc(cur.stage) + '</div>' +
        '<div class="gs-trk-stage-sub">' + esc(cur.detail || '') + '</div>';
    }

    var dotsHtml = steps.map(function (e, i) {
      var reached = i < current;
      var isNow = i === current - 1;
      var cls = ['gs-trk-step'];
      if (reached && !isNow) cls.push('done');
      if (isNow) cls.push('now');
      if (viewIndex === i) cls.push('viewing');
      if (reached) cls.push('clickable');
      if (e.isRegression) cls.push('regression');

      /* El ícono de este puntito refleja la etapa en que quedo la
         orden DESPUES de este evento (e.resultStage) -- el llamador
         ya lo calculo caminando el historial (avanza/retrocede/se
         queda igual segun el tipo de evento real). No es un conteo
         que solo pueda subir. */
      var stageHere = (reached || isNow) ? (e.resultStage || 0) : 0;
      var triFrac = triFracFor(stageHere, triangleMaxStage);
      var dashoffset = triLen - triFrac * triLen;
      var gFrac = (gStage && stageHere >= gStage) ? 1 : 0;
      var sFrac = (sStage && stageHere >= sStage) ? 1 : 0;
      /* 0/55 y 50/100: la G real ocupa del 0% al ~52% del ancho del
         lienzo (900px) y la S del ~52% al 100% (medido directo de los
         PNG). El avance tiene que moverse DENTRO de esos rangos, no
         del lienzo completo -- si no, tapar "la mitad del lienzo"
         tapaba de mas la S (que vive del lado derecho).

         En vez de un corte recto (clip-path), se usa un degradado
         (mask-image) en angulo con una franja de transicion suave --
         se ve como la letra "creciendo" en diagonal, no cortada de
         tajo con tijeras. */
      var FEATHER = 7; // ancho de la zona difuminada, en % del ancho del lienzo
      function maskFor(boundaryPct) {
        var a = Math.max(0, boundaryPct - FEATHER);
        var b = Math.min(100, boundaryPct + FEATHER);
        return 'linear-gradient(100deg, #000 0%, #000 ' + a + '%, transparent ' + b + '%, transparent 100%)';
      }
      var gMask = maskFor(0 + gFrac * 55);
      var sMask = maskFor(50 + sFrac * 50);

      return '<div class="' + cls.join(' ') + '" data-idx="' + i + '">' +
        '<div class="gs-trk-dot">' +
          '<svg class="gs-trk-dot-icon" viewBox="0 0 900 851">' +
            '<path class="gs-trk-dot-gold" style="stroke-dasharray:' + triLen + ';stroke-dashoffset:' + dashoffset + '" d="' + TRI_D + '"/>' +
          '</svg>' +
          '<div class="gs-trk-dot-letters">' +
            '<img style="opacity:' + (gFrac > 0 ? 1 : 0) + ';-webkit-mask-image:' + gMask + ';mask-image:' + gMask + '" src="' + LAYER_G + '" alt="">' +
            '<img style="opacity:' + (sFrac > 0 ? 1 : 0) + ';-webkit-mask-image:' + sMask + ';mask-image:' + sMask + '" src="' + LAYER_S + '" alt="">' +
          '</div>' +
        '</div>' +
        '<div class="gs-trk-step-label">' + esc(e.label) + '</div>' +
      '</div>';
    }).join('');

    el.innerHTML =
      '<div class="gs-trk-scroll"><div class="gs-trk-tracker">' + dotsHtml + '</div></div>' +
      '<div class="gs-trk-stage-row">' + stageHtml + '</div>';

    Array.prototype.forEach.call(el.querySelectorAll('.gs-trk-step.clickable'), function (stepEl) {
      stepEl.addEventListener('click', function () {
        inst.viewIndex = parseInt(stepEl.getAttribute('data-idx'), 10);
        render(fieldId);
      });
    });
  }

  function mount(fieldId, containerId, options) {
    styleTag();
    instances[fieldId] = {
      steps: (options && options.steps) || [],
      current: (options && options.current) || 0,
      viewIndex: null,
      containerId: containerId,
      gStage: (options && options.gStage) || 0,
      sStage: (options && options.sStage) || 0,
      triangleMaxStage: (options && options.triangleMaxStage) || 0
    };
    render(fieldId);
  }

  /* Se llama cuando el avance REAL de la orden cambia (llego un evento
     nuevo del historial). Siempre saca al usuario del modo "revisando
     un paso anterior" y regresa la vista al paso actual real. */
  function setCurrent(fieldId, n) {
    var inst = instances[fieldId];
    if (!inst) return;
    inst.current = n;
    inst.viewIndex = null;
    render(fieldId);
  }

  function getCurrent(fieldId) {
    var inst = instances[fieldId];
    return inst ? inst.current : 0;
  }

  window.GSOrderTracker = {
    mount: mount,
    setCurrent: setCurrent,
    getCurrent: getCurrent
  };
})();
